    "patient_family_realworld_adaptation": "excellent"
  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00061",
          "explanation": "Doctor specifically asks about who gives drops and when caregivers change, and then integrates the family’s stated rotating fatigue into a simple, fixed-time schedule.",
          "quote": "如果今天下午老人实在不愿意去，明天上午去完全来得及，不会有太大问题"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor elicited the family’s practical barriers (rotating caregivers, uncertain missed-dose handling, patient resistance) and translated them into a concrete, low-burden system: a paper check-off sheet posted on the refrigerator, a single fixed time grid, and a clear rule for missed doses. The plan was adapted to the family's actual constraints and received caregiver teach-back.",
